package com.aditya.day13.restaurant; import jakarta.persistence.*; import java.util.*; @Entity public class Restaurant{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;String name;boolean open;public UUID getId(){return id;}public String getName(){return name;}public void setName(String x){name=x;}public boolean isOpen(){return open;}public void setOpen(boolean x){open=x;}}